	for _, snap := range snapshots {
		// Reward warm caches, scaled by session affinity
		cacheBoost := 0.3
		if req.SessionID != "" {
			cacheBoost = 0.5
		}
		scores[snap.ID] += snap.CacheHitRate * cacheBoost

		// Memory pressure penalty
		if snap.KVUtilization > 0.9 {
			scores[snap.ID] *= 0.25
