		scores[snap.ID] *= 1.0 / (1.0 + float64(el)*float64(el)*0.04)

		// Queue depth spike protection
		if snap.QueueDepth > 10 {
			scores[snap.ID] *= 0.15
		} else if snap.QueueDepth > 6 {
			scores[snap.ID] *= 0.35
		} else if snap.QueueDepth > 3 {
			scores[snap.ID] *= 0.6
		}
	}

	// Argmax with tie-breaking by lowest effective load
	bestScore := -1.0
	bestIdx := 0
	for i, snap := range snapshots {
		if scores[snap.ID] > bestScore {
			bestScore = scores[snap.ID]
			bestIdx = i
		} else if scores[snap.ID] == bestScore && snap.EffectiveLoad() < snapshots[bestIdx].EffectiveLoad() {
			bestIdx = i
		}
	}
	_ = bestIdx // ensure used before final selection below

	// Re-select to be safe
	bestScore = -1.0
	bestIdx = 0
	for i, snap := range snapshots {
		if scores[snap.ID] > bestScore {
			bestScore = scores[snap.ID]
			bestIdx = i
		}
	}
